{
"rules": [
{
"id": "r1",
"text": "If the chart's y-axis is read as temperature in Celsius and the x-axis as year, then the period-wide change from 2005 to 2014 is the difference between the first and last labeled data points; a large absolute difference supports substantial-change follow-up, while a small difference supports routine monitoring.",
"component": "encoding/task relation",
"conditions": "Assumes the printed point labels are the intended data values and that the task's 'large enough' threshold is not numerically specified, so magnitude is judged qualitatively."
},
{
"id": "r2",
"text": "If the task requires a specific numeric threshold to distinguish substantial change from ordinary variation, and no such threshold is provided in the public task or policy tables, then the routing decision is underdetermined and cannot be conclusively assigned to either follow-up or routine monitoring.",
"component": "task-to-action relation",
"conditions": "Applies when the public task defines the criterion only qualitatively as 'large enough' or 'ordinary enough' without a numeric cutoff."
},
{
"id": "r3",
"text": "If the chart's y-axis label and point labels are treated as literal inscriptions rather than validated measurements, then the visible drop from the 2005 label to the 2014 label is a raw visual fact, but its interpretation as a 'substantial' temperature change depends on the missing policy threshold.",
"component": "scale comparability",
"conditions": "Preserves the distinction between raw printed values and derived business meaning; does not assume the printed values are true."
}
],
"chains": [
{
"chain_id": "base_c1",
"rule_id": "r1",
"observations": [
{
"ref": "chart_1",
"location": "top-left data point",
"content": "A black dot is positioned above the x-axis tick '2005', with the printed label '$23.9°C' directly above it."
},
{
"ref": "chart_1",
"location": "bottom-right data point",
"content": "A black dot is positioned above the x-axis tick '2014', with the printed label '$10.1°C' directly above it."
},
{
"ref": "chart_1",
"location": "y-axis",
"content": "The vertical axis is labeled 'Temperature (°C)' with visible ticks at 0, 5, 10, 15, and 20."
}
],
